from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Callable

from mage_agent.core.config import AgentConfig, load_config
from mage_agent.core.http import MageApiClient
from mage_agent.tools.blocks import BlockTools
from mage_agent.tools.executions import ExecutionTools
from mage_agent.tools.pipelines import PipelineTools
from mage_agent.tools.sync import SyncTools
from mage_agent.tools.workspaces import WorkspaceTools

ToolHandler = Callable[[dict[str, Any]], Any]


@dataclass
class ToolDef:
    name: str
    description: str
    input_schema: dict[str, Any]
    handler: ToolHandler


@dataclass
class SkillRuntime:
    config: AgentConfig

    @classmethod
    def from_config(cls) -> "SkillRuntime":
        return cls(config=load_config())

    def _api(self) -> MageApiClient:
        return MageApiClient(self.config)

    def pipelines(self) -> PipelineTools:
        return PipelineTools(self._api())

    def blocks(self) -> BlockTools:
        return BlockTools(self._api())

    def executions(self) -> ExecutionTools:
        return ExecutionTools(self._api())

    def sync(self) -> SyncTools:
        return SyncTools(self._api())

    def workspaces(self) -> WorkspaceTools:
        return WorkspaceTools(self.config)


_PIPELINE_EXECUTION_DESCRIPTION = (
    "Run a pipeline end to end: create inactive run-once schedule, start a "
    "pipeline run, poll to completion, collect block runs, outputs, and failure "
    "logs. `run_pipeline` and `execute_pipeline` are aliases with identical "
    "behavior. See skill://executions for guidance."
)

_PIPELINE_EXECUTION_INPUT_SCHEMA: dict[str, Any] = {
    "type": "object",
    "properties": {
        "pipeline_uuid": {"type": "string"},
        "variables": {"type": "object"},
        "payload": {
            "type": "object",
            "description": (
                "Optional execution options (variables, timeout, schedule_payload, "
                "include_outputs, etc.). Top-level parameters override payload fields."
            ),
        },
        "poll_interval_seconds": {"type": "integer", "minimum": 1},
        "timeout_seconds": {"type": "integer", "minimum": 1},
        "schedule_payload": {"type": "object"},
        "include_outputs": {"type": "boolean"},
        "sample_count": {"type": "integer", "minimum": 1},
        "include_log_content": {"type": "boolean"},
        "max_log_chars": {"type": "integer", "minimum": 1},
    },
    "required": ["pipeline_uuid"],
    "additionalProperties": False,
}

_PIPELINE_RUN_ID_SCHEMA: dict[str, Any] = {
    "oneOf": [
        {"type": "integer"},
        {"type": "string", "pattern": "^\\d+$"},
    ],
    "description": "Numeric pipeline run ID.",
}

_PIPELINE_EXECUTION_OPTION_KEYS = (
    "variables",
    "poll_interval_seconds",
    "timeout_seconds",
    "schedule_payload",
    "include_outputs",
    "sample_count",
    "include_log_content",
    "max_log_chars",
)


def _handle_pipeline_execution(args: dict[str, Any]) -> Any:
    options = dict(args.get("payload") or {})
    for key in _PIPELINE_EXECUTION_OPTION_KEYS:
        if key in args and args[key] is not None:
            options[key] = args[key]
    return (
        SkillRuntime.from_config()
        .executions()
        .run_pipeline(args["pipeline_uuid"], options or None)
    )


def build_tools() -> list[ToolDef]:
    return [
        ToolDef(
            name="workspace_list",
            description=(
                "List Mage Pro workspaces from either a workspace management URL "
                "(project_type=main) or a workspace URL (project_type=sub); "
                "standalone is not supported. "
                "See skill://workspaces for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {},
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .workspaces()
            .list_workspaces(),
        ),
        ToolDef(
            name="workspace_switch",
            description=(
                "Switch workspace: set cluster_url to {management_base}/{workspace_name}, "
                "persist config, verify via GET /api/status. "
                "See skill://workspaces for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "workspace_name": {
                        "type": "string",
                        "description": "Workspace name from workspace_list.",
                    },
                },
                "required": ["workspace_name"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .workspaces()
            .switch_workspace(args["workspace_name"]),
        ),
        ToolDef(
            name="pipeline_list",
            description="List pipelines. See skill://pipeline for guidance.",
            input_schema={
                "type": "object",
                "properties": {},
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .pipelines()
            .list_pipelines(),
        ),
        ToolDef(
            name="pipeline_get",
            description=(
                "Get one pipeline by UUID. "
                "See skill://pipeline for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {"uuid": {"type": "string"}},
                "required": ["uuid"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .pipelines()
            .get_pipeline(args["uuid"]),
        ),
        ToolDef(
            name="pipeline_create",
            description=(
                "Create a pipeline. "
                "See skill://pipeline for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "name": {"type": "string"},
                    "type": {
                        "type": "string",
                        "enum": ["python", "streaming", "integration"],
                    },
                    "payload": {"type": "object"},
                },
                "required": ["name"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .pipelines()
            .create_pipeline(
                args["name"],
                {
                    "type": args["type"],
                    **(args.get("payload") or {}),
                }
                if args.get("type")
                else args.get("payload"),
            ),
        ),
        ToolDef(
            name="pipeline_update",
            description=(
                "Update pipeline fields. "
                "See skill://pipeline for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "uuid": {"type": "string"},
                    "payload": {"type": "object"},
                },
                "required": ["uuid", "payload"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .pipelines()
            .update_pipeline(args["uuid"], args["payload"]),
        ),
        ToolDef(
            name="pipeline_delete",
            description=(
                "Delete a pipeline by UUID. "
                "See skill://pipeline for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {"uuid": {"type": "string"}},
                "required": ["uuid"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .pipelines()
            .delete_pipeline(args["uuid"]),
        ),
        ToolDef(
            name="block_list",
            description=(
                "List blocks for a pipeline. "
                "See skill://blocks for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {"pipeline_uuid": {"type": "string"}},
                "required": ["pipeline_uuid"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .blocks()
            .list_blocks(args["pipeline_uuid"]),
        ),
        ToolDef(
            name="block_get",
            description="Get block details. See skill://blocks for guidance.",
            input_schema={
                "type": "object",
                "properties": {
                    "pipeline_uuid": {"type": "string"},
                    "block_uuid": {"type": "string"},
                },
                "required": ["pipeline_uuid", "block_uuid"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config().blocks().get_block(
                args["pipeline_uuid"],
                args["block_uuid"],
            ),
        ),
        ToolDef(
            name="block_create",
            description="Create a block. See skill://blocks for guidance.",
            input_schema={
                "type": "object",
                "properties": {
                    "pipeline_uuid": {"type": "string"},
                    "name": {"type": "string"},
                    "type": {
                        "type": "string",
                        "enum": [
                            "callback",
                            "chart",
                            "conditional",
                            "custom",
                            "data_exporter",
                            "data_loader",
                            "dbt",
                            "extension",
                            "global_data_product",
                            "markdown",
                            "scratchpad",
                            "sensor",
                            "transformer",
                        ],
                    },
                    "language": {
                        "type": "string",
                        "enum": ["python", "sql", "r", "yaml", "markdown"],
                    },
                    "content": {"type": "string"},
                    "upstream_blocks": {
                        "type": "array",
                        "items": {"type": "string"},
                    },
                    "config": {"type": "object"},
                    "payload": {"type": "object"},
                },
                "required": ["pipeline_uuid", "name", "type"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .blocks()
            .create_block(
                pipeline_uuid=args["pipeline_uuid"],
                name=args["name"],
                block_type=args["type"],
                language=args.get("language", "python"),
                content=args.get("content"),
                upstream_blocks=args.get("upstream_blocks"),
                config=args.get("config"),
                payload=args.get("payload"),
            ),
        ),
        ToolDef(
            name="block_templates_list",
            description=(
                "List available block templates. "
                "See skill://blocks for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "force_refresh": {"type": "boolean"},
                },
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .blocks()
            .list_block_templates(force_refresh=args.get("force_refresh", False)),
        ),
        ToolDef(
            name="block_update",
            description=(
                "Update block fields. "
                "See skill://blocks for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "pipeline_uuid": {"type": "string"},
                    "block_uuid": {"type": "string"},
                    "payload": {"type": "object"},
                },
                "required": ["pipeline_uuid", "block_uuid", "payload"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .blocks()
            .update_block(
                args["pipeline_uuid"],
                args["block_uuid"],
                args["payload"],
            ),
        ),
        ToolDef(
            name="execute_pipeline",
            description=_PIPELINE_EXECUTION_DESCRIPTION,
            input_schema=_PIPELINE_EXECUTION_INPUT_SCHEMA,
            handler=_handle_pipeline_execution,
        ),
        ToolDef(
            name="run_pipeline",
            description=_PIPELINE_EXECUTION_DESCRIPTION,
            input_schema=_PIPELINE_EXECUTION_INPUT_SCHEMA,
            handler=_handle_pipeline_execution,
        ),
        ToolDef(
            name="run_logs",
            description=(
                "Fetch logs for a pipeline run. "
                "See skill://executions for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "pipeline_uuid": {"type": "string"},
                    "run_id": {
                        **_PIPELINE_RUN_ID_SCHEMA,
                        "description": "Pipeline run ID (from run_pipeline / execute_pipeline).",
                    },
                },
                "required": ["pipeline_uuid", "run_id"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .executions()
            .get_logs(
                args["pipeline_uuid"],
                args["run_id"],
            ),
        ),
        ToolDef(
            name="run_block",
            description=(
                "Execute a single block synchronously via POST /api/runs using the "
                "pipeline API trigger token (OAuth is only used to find/create the "
                "trigger). See skill://executions for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "pipeline_uuid": {"type": "string"},
                    "block_uuid": {"type": "string"},
                    "variables": {"type": "object"},
                    "record": {"type": "boolean"},
                    "store_variables": {"type": "boolean"},
                    "run_upstream_blocks": {"type": "boolean"},
                    "incomplete_only": {"type": "boolean"},
                    "timeout_seconds": {"type": "integer", "minimum": 1},
                    "payload": {
                        "type": "object",
                        "description": (
                            "Optional fields merged into the run body last "
                            "(or a nested run object)."
                        ),
                    },
                },
                "required": ["pipeline_uuid", "block_uuid"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .executions()
            .run_block(
                args["pipeline_uuid"],
                args["block_uuid"],
                variables=args.get("variables"),
                record=args.get("record", True),
                store_variables=args.get("store_variables", True),
                run_upstream_blocks=args.get("run_upstream_blocks", False),
                incomplete_only=args.get("incomplete_only", False),
                payload=args.get("payload"),
                timeout_seconds=args.get("timeout_seconds", 600),
            ),
        ),
        ToolDef(
            name="block_run_outputs",
            description=(
                "List block runs for a pipeline run and fetch outputs per block run "
                "via GET /api/block_runs/:block_run_id/outputs. "
                "See skill://executions for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "pipeline_run_id": _PIPELINE_RUN_ID_SCHEMA,
                    "sample_count": {
                        "type": "integer",
                        "minimum": 1,
                        "description": "Max rows per output (default 100).",
                    },
                },
                "required": ["pipeline_run_id"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .executions()
            .get_block_run_outputs(
                args["pipeline_run_id"],
                sample_count=args.get("sample_count", 100),
            ),
        ),
        ToolDef(
            name="sync_project_to_local",
            description=(
                "Sync project source files to local disk. "
                "See skill://sync for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "local_project_dir": {"type": "string"},
                },
                "required": ["local_project_dir"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .sync()
            .sync_project_to_local(args["local_project_dir"]),
        ),
        ToolDef(
            name="sync_status",
            description=(
                "Compute remote/local sync status and conflicts. "
                "See skill://sync for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "local_project_dir": {"type": "string"},
                },
                "required": ["local_project_dir"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .sync()
            .sync_status(args["local_project_dir"]),
        ),
        ToolDef(
            name="sync_local_to_remote",
            description=(
                "Sync changed local source files to remote project. "
                "See skill://sync for guidance."
            ),
            input_schema={
                "type": "object",
                "properties": {
                    "local_project_dir": {"type": "string"},
                },
                "required": ["local_project_dir"],
                "additionalProperties": False,
            },
            handler=lambda args: SkillRuntime.from_config()
            .sync()
            .sync_local_to_remote(args["local_project_dir"]),
        ),
    ]
